'use strict';
// All combat names, ability assignments and values here are prototype rules.
const FX={effects:[],shots:[],cut:null,paused:false,warping:null,serial:0,
 names:['ブレイズスラッシュ','ヒーリングバレット','ペイントバースト','幻影の貫通弾'],
 abilities:['ボムガード','スパイクガード','ペイントリペア','ワープガード'],
 reset(){this.effects=[];this.shots=[];this.cut=null;this.warping=null;this.serial++;this.paused=false;this.shotStopped=false;S.gimmicks=S.stage===0?[{type:'bomb',x:270,y:475,r:19,used:false}]:[{type:'bomb',x:270,y:300,r:20,used:false},{type:'spike',x:70,y:440,w:150,h:18},{type:'warp',x:90,y:220,r:23,exit:1},{type:'warp',x:455,y:470,r:23,exit:0},{type:'heavy',x:300,y:110,w:150,h:55}];S.gimmickCooldown={};},
 add(type,x,y,color='#d9ff60',life=.55,extra={}){this.effects.push({type,x,y,color,life,t:life,...extra});if(this.effects.length>140)this.effects.shift()},
 label(x,y,text,color='#fff'){this.add('label',x,y,color,.9,{text})},
 launch(){this.shotStopped=false;if(S.armed&&globalThis.HunterSkills&&!S.training&&HunterSkills.launch())return;if(S.armed){const h=hunters[S.active],u=S.units[S.active];if(h.role===1){S.hp=Math.min(S.maxHp,S.hp+15);this.shield(u.x,u.y,'HS / HP＋15')}if(h.role===2){for(let dx=-60;dx<=60;dx+=10)for(let dy=-60;dy<=60;dy+=10)if(dx*dx+dy*dy<=3600)mark(u.x+dx,u.y+dy,u.x+dx,u.y+dy)}if(h.role===3){u.vx*=1.2;u.vy*=1.2;}this.cut={t:1.05,life:1.05,name:hunters[S.active].name,index:S.active};tone(650);}},
 fireLink(f,i,target){const role=hunters[i].role,color=hunters[i].color;if(Math.hypot(target.x-f.x,target.y-f.y)>hunters[i].range){this.label(f.x,f.y-38,'LC 射程外',color);return;}if(S.stats)S.stats.links++;this.add('aura',f.x,f.y,color,.6);this.label(f.x,f.y-38,hunters[i].lc,color);this.shots.push({x:f.x,y:f.y,fromX:f.x,fromY:f.y,target,damage:linkDamage(f),hunterIndex:i,color,role,delay:.16,age:0});tone(700);},
 step(dt){
  for(const e of this.effects)e.t-=dt;this.effects=this.effects.filter(e=>e.t>0);
  if(!S||S.done)return;
  if(this.cut){this.cut.t-=dt;if(this.cut.t<=0)this.cut=null;return;}
  if(this.warping){let w=this.warping;w.t-=dt;if(w.t<=0){let u=S.units[S.active];u.x=w.x;u.y=w.y;this.add('portal',u.x,u.y,'#b695ff',.6);this.warping=null;}return;}
  for(const p of this.shots){p.age+=dt;if(p.delay>0){p.delay-=dt;continue}if(p.target.hp<=0){p.target=S.enemies.filter(e=>e.hp>0).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(!p.target){p.done=true;continue}}let dx=p.target.x-p.x,dy=p.target.y-p.y,d=Math.hypot(dx,dy),step=850*dt;if(d<=step+p.target.r){hit(p.target,p.damage);if(p.role===1)S.hp=Math.min(S.maxHp,S.hp+3);if(p.role===2)for(const e of S.enemies){if(e!==p.target&&e.hp>0&&Math.hypot(e.x-p.target.x,e.y-p.target.y)<=100)hit(e,Math.round(p.damage*.5))}if(p.role===3){const dx=p.target.x-p.fromX,dy=p.target.y-p.fromY,len=Math.hypot(dx,dy)||1;for(const e of S.enemies){const t=((e.x-p.fromX)*dx+(e.y-p.fromY)*dy)/(len*len),d=Math.abs((e.x-p.fromX)*dy-(e.y-p.fromY)*dx)/len;if(e!==p.target&&e.hp>0&&t>=0&&t<=1&&d<e.r+10)hit(e,Math.round(p.damage*.6))}}this.add(p.role===2?'blast':p.role===0?'slash':'impact',p.target.x,p.target.y,p.color,.55);p.done=true;}else{p.x+=dx/d*step;p.y+=dy/d*step;}if(p.age>3)p.done=true;}
  this.shots=this.shots.filter(p=>!p.done);
  if(this.shotStopped&&!this.shots.length){this.shotStopped=false;endTurn();}
 },
 block(){return !!(this.cut||this.warping||this.shotStopped)},
 shield(x,y,text){this.add('shield',x,y,'#8fffe0',.7);this.label(x,y-45,text,'#8fffe0');tone(900)},
 hurt(x,y,d){S.hp=Math.max(0,S.hp-d);this.label(x,y-28,'HP −'+d,'#ff718e');this.add('impact',x,y,'#ff718e',.6);if(!S.hp)finish(false);},
 gimmicks(dt){if(!S||S.done||this.warping)return;let u=S.units[S.active],role=hunters[S.active].role;
  for(let i=0;i<S.gimmicks.length;i++){let g=S.gimmicks[i],touch=(g.type==='spike'||g.type==='heavy')?u.x>g.x-u.r&&u.x<g.x+g.w+u.r&&u.y>g.y-u.r&&u.y<g.y+g.h+u.r:Math.hypot(u.x-g.x,u.y-g.y)<u.r+g.r;if(!touch)continue;
   if(g.type==='heavy'){if(Growth.has(hunters[S.active],'レジヘヴィ')){if(!S.gimmickCooldown.heavy){this.shield(u.x,u.y,'レジヘヴィ');S.gimmickCooldown.heavy=1}}else{u.vx*=Math.exp(-2.4*dt);u.vy*=Math.exp(-2.4*dt);}continue;}
   if(g.type==='bomb'&&!g.used){g.used=true;this.add('blast',g.x,g.y,'#ffb25d',.75);for(let j=0;j<18;j++)this.add('spark',g.x,g.y,'#ffe278',.5,{vx:Math.cos(j)*170,vy:Math.sin(j)*170});if(Growth.has(hunters[S.active],'レジボム'))this.shield(u.x,u.y,'ボムガード / 破壊');else this.hurt(g.x,g.y,8);for(const e of S.enemies)if(e.hp>0&&Math.hypot(e.x-g.x,e.y-g.y)<125)hit(e,35);}
   if(g.type==='spike'&&S.elapsed>(S.gimmickCooldown.spike??-1)){S.gimmickCooldown.spike=S.elapsed+.75;for(let j=0;j<7;j++)this.add('spark',u.x,u.y,'#ffe278',.45,{vx:(Math.random()-.5)*200,vy:-Math.random()*170});if(Growth.has(hunters[S.active],'レジスパイク'))this.shield(u.x,u.y,'スパイクガード');else this.hurt(u.x,u.y,5);}
   if(g.type==='warp'&&S.elapsed>(S.gimmickCooldown.warp??-1)){S.gimmickCooldown.warp=S.elapsed+1.2;if(Growth.has(hunters[S.active],'レジワープ')){this.shield(u.x,u.y,'ワープガード');continue}const ends=S.gimmicks.filter(v=>v.type==='warp'),out=ends[g.exit];this.add('portal',u.x,u.y,'#b695ff',.5);this.warping={t:.3,x:out.x,y:out.y};this.label(u.x,u.y-35,'WARP','#d3b2ff');break;}
  }
 },
 repair(){if(!Growth.has(hunters[S.active],'ペイントリペア')&&hunters[S.active].role!==2)return;let u=S.units[S.active];for(let dx=-30;dx<=30;dx+=10)for(let dy=-30;dy<=30;dy+=10)mark(u.x+dx,u.y+dy,u.x+dx,u.y+dy);this.shield(u.x,u.y,'ペイントリペア / 塗り返し');},
 drawGimmicks(){if(!S)return;let t=performance.now()/1000;for(const g of S.gimmicks){ctx.save();if(g.type==='bomb'&&!g.used){circle(g.x,g.y,g.r+3+Math.sin(t*6)*2,'#ffb25d44');circle(g.x,g.y,g.r,'#402f32');ctx.fillStyle='#ffd787';ctx.font='bold 18px system-ui';ctx.textAlign='center';ctx.fillText('B',g.x,g.y+6)}if(g.type==='heavy'){ctx.fillStyle='#10131ddd';ctx.fillRect(g.x,g.y,g.w,g.h);ctx.fillStyle='#a7a0be';ctx.font='12px system-ui';ctx.textAlign='center';ctx.fillText('HEAVY',g.x+g.w/2,g.y+g.h/2)}if(g.type==='spike'){ctx.fillStyle='#ff7d9e';for(let x=g.x;x<g.x+g.w;x+=15){ctx.beginPath();ctx.moveTo(x,g.y+g.h);ctx.lineTo(x+7,g.y);ctx.lineTo(x+14,g.y+g.h);ctx.fill()}}if(g.type==='warp'){ctx.translate(g.x,g.y);ctx.rotate(t*(g.exit?1:-1));ctx.strokeStyle='#b695ff';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(0,0,25,18,0,0,Math.PI*2);ctx.stroke();ctx.rotate(t);ctx.strokeStyle='#83dcff';ctx.strokeRect(-13,-13,26,26)}ctx.restore()}},
 draw(){for(const p of this.shots){if(p.delay>0)continue;ctx.save();ctx.strokeStyle=p.color;ctx.lineWidth=p.role===0?9:4;ctx.globalAlpha=.55;ctx.beginPath();ctx.moveTo(p.fromX,p.fromY);ctx.lineTo(p.x,p.y);ctx.stroke();circle(p.x,p.y,p.role===2?12:7,p.color);ctx.restore()}
  for(const e of this.effects){let a=1-e.t/e.life;ctx.save();ctx.globalAlpha=Math.max(0,e.t/e.life);ctx.strokeStyle=e.color;ctx.fillStyle=e.color;ctx.lineWidth=3;if(e.type==='label'){ctx.font='bold 17px system-ui';ctx.textAlign='center';ctx.fillText(e.text,Math.max(95,Math.min(445,e.x)),e.y-a*24)}else if(e.type==='spark'){circle(e.x+(e.vx||0)*a*e.life,e.y+(e.vy||0)*a*e.life,3,e.color)}else if(e.type==='splash'){circle(e.x,e.y,3+a*9,e.color)}else if(e.type==='slash'){ctx.translate(e.x,e.y);ctx.rotate(-.7+a);ctx.lineWidth=8*(1-a);ctx.beginPath();ctx.ellipse(0,0,12+a*45,9,0,0,Math.PI*2);ctx.stroke()}else{let r=e.type==='blast'?15+a*105:e.type==='shield'?35:12+a*42;ctx.beginPath();ctx.arc(e.x,e.y,r,0,Math.PI*2);ctx.stroke();if(e.type==='blast'||e.type==='impact'){circle(e.x,e.y,(1-a)*22,e.color)}}ctx.restore()}
  if(this.cut){let c=this.cut,progress=1-c.t/c.life,alpha=Math.min(1,progress*8,c.t*6),slide=Math.max(0,1-progress*5)*180;ctx.save();ctx.globalAlpha=alpha;ctx.fillStyle='#070c1ee8';ctx.fillRect(0,160,540,320);ctx.translate(slide,0);const art=ART[c.name];if(art&&art.image.complete&&art.image.naturalWidth){ctx.drawImage(art.image,...art.rect,24,177,210,264)}else if(globalThis.VISUALS&&VISUALS.drawAsset(ctx,c.name,'editor',24,177,210,264)){}else{circle(120,305,68,hunters[c.index].color);ctx.fillStyle='#152035';ctx.font='bold 60px system-ui';ctx.textAlign='center';ctx.fillText(hunters[c.index].mark,120,325)}ctx.textAlign='left';ctx.fillStyle='#d9ff60';ctx.font='bold 15px system-ui';ctx.fillText('HUNTER SKILL',252,245);ctx.fillStyle='#fff';ctx.font='bold 25px system-ui';let name=c.name;ctx.fillText(name,252,292,265);ctx.font='bold 18px system-ui';ctx.fillText(hunters[c.index].hs,252,333,265);ctx.fillStyle='#9dacbf';ctx.font='13px system-ui';ctx.fillText('一撃で、盤面を塗り変えろ。',252,370);ctx.restore();}
 }
};
const ART={};
for(const [file,names] of [['01','アイギス アイリス アケディア アケノ アザレア 花見のアザレア アズネ アーベル 花見のアーベル アマナ 祝音のアマナ アヤメ アリス 聖夜のアリス 幻想のアリス アルカナ'],['05','甘味のキリカ ギンジ 執事のギンジ グラトニー クララ クランプス 礼装のクランプス グリード グリフィズ クレア 仮装のクレア 祝宴のクレア クレハ クロウ クロエ コニー'],['13','ユエ ユオ ユーベル ユニス 花見のユニス ユリン 花見のユリン ヨミ 月見のヨミ ラース ライカ ライゼ ラジエル ラスト ラム 花嫁のラム']]){let image=new Image();image.src='assets/catalog-'+file+'.jpg';names.split(' ').forEach((name,i)=>{let x=i%4,y=Math.floor(i/4);ART[name]={image,rect:[8+x*278,58+y*328,270,317]}})}
